{"t":"say","text":"Single agent pattern: reads supplier invoices from email, cross-checks PO and GRN via ERP tools, then posts approved entries."}
{"t":"assume","id":"erp-adapter","text":"ERP exposes REST APIs for PO, GRN lookup and invoice posting","alt":"Custom DB adapter required for legacy ERP"}
{"t":"assume","id":"invoice-format","text":"Invoices arrive as PDF attachments in supplier emails","alt":"Invoices embedded directly in email body text"}
{"t":"ask","id":"volume","text":"하루에 처리할 공급업체 인보이스 이메일은 대략 몇 건입니까?"}
{"t":"ask","id":"success","text":"성공 기준(예: 자동 등록률)과 현재 수동 처리 기준선은 어떻게 됩니까?"}
{"t":"step","id":"email-in","kind":"trigger","label":"Supplier invoice email","product":"eventbridge","runs":"fc","untrusted":true,"why":"Inbound supplier email is untrusted external content"}
{"t":"step","id":"parse-pdf","kind":"tool","label":"Extract invoice PDF","task":"extract","tool":"pdf_parse","runs":"agentrun","effect":"read","untrusted":true,"why":"Parse attached PDF invoices into structured text"}
{"t":"step","id":"invoice-agent","kind":"agent","label":"Reconcile and post invoice","task":"plan","ai":"qwen3.7-plus","turns":10,"runs":"agentrun","private":true,"approval":"required","why":"Orchestrate multi-step reconciliation across ERP systems with write access"}
{"t":"step","id":"lookup-po","kind":"tool","label":"Lookup purchase order","task":"retrieve","runs":"customer","effect":"read","on":"invoice-agent","private":true,"why":"Fetch PO details from customer ERP to match invoice line items"}
{"t":"step","id":"lookup-grn","kind":"tool","label":"Lookup goods receipt","task":"retrieve","runs":"customer","effect":"read","on":"invoice-agent","private":true,"why":"Fetch GRN records from customer ERP to verify received quantities"}
{"t":"step","id":"post-erp","kind":"tool","label":"Post invoice to ERP","task":"generate","runs":"customer","effect":"write","on":"invoice-agent","private":true,"approval":"required","why":"Write approved and reconciled invoice record into the ERP system"}
{"t":"step","id":"guard-out","kind":"guard","label":"Screen outbound data","product":"ai-guardrails","runs":"fc","why":"Prevent private ERP data leakage or harmful content before notification"}
{"t":"step","id":"notify","kind":"act","label":"Notify finance team","effect":"notify","product":"direct-mail","runs":"fc","why":"Alert finance team of successful postings or manual review needs"}
{"t":"step","id":"posted","kind":"end","label":"Invoice posted","runs":"customer"}
{"t":"step","id":"failed","kind":"end","label":"Reconciliation failed","runs":"customer"}
{"t":"link","id":"in-parse","from":"email-in","to":"parse-pdf"}
{"t":"link","id":"parse-agent","from":"parse-pdf","to":"invoice-agent"}
{"t":"link","id":"agent-guard","from":"invoice-agent","to":"guard-out"}
{"t":"link","id":"agent-failed","from":"invoice-agent","to":"failed","kind":"branch","label":"Reconciliation mismatch"}
{"t":"link","id":"guard-notify","from":"guard-out","to":"notify"}
{"t":"link","id":"notify-posted","from":"notify","to":"posted"}
{"t":"done","summary":"AgentRun-based single agent that extracts PDF invoices, reconciles against ERP PO/GRN via attached tools, and posts approved entries with guard and approval."}

{"t":"say","text":"Prompt chain pattern: retrieve policy, generate grounded answer or refuse, guard output, escalate unverified questions to HR."}
{"t":"assume","id":"channel","text":"Chat channel is internal web chat via AgentCore connector"}
{"t":"assume","id":"kb","text":"Policy knowledge base uses DashVector with text-embedding-v4"}
{"t":"step","id":"chat-in","kind":"trigger","label":"Employee question","product":"agentcore","runs":"customer","untrusted":true,"why":"Entry point for employee chat messages"}
{"t":"step","id":"input-guard","kind":"guard","label":"Screen input","product":"ai-guardrails","runs":"fc","why":"Detect prompt injection in untrusted chat input"}
{"t":"step","id":"embed","kind":"knowledge","label":"Embed query","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","effect":"read","why":"Convert question to vector for policy search"}
{"t":"step","id":"search","kind":"knowledge","label":"Search policies","task":"retrieve","product":"dashvector","runs":"fc","effect":"read","why":"Retrieve relevant policy chunks from vector store"}
{"t":"step","id":"rerank","kind":"knowledge","label":"Rerank results","task":"rerank","ai":"qwen3-rerank","runs":"fc","why":"Score and rank retrieved chunks by relevance"}
{"t":"step","id":"answer","kind":"ai","label":"Generate or refuse","task":"generate","ai":"qwen3.7-plus","runs":"fc","why":"Answer using evidence or refuse if insufficient grounds"}
{"t":"step","id":"output-guard","kind":"guard","label":"Screen reply","product":"ai-guardrails","runs":"fc","why":"Prevent private data leaks before delivery"}
{"t":"step","id":"route","kind":"decide","label":"Route response","task":"check","ai":"qwen3.8-flash","runs":"fc","why":"Decide whether to deliver answer or escalate to HR"}
{"t":"step","id":"deliver","kind":"act","label":"Reply to employee","effect":"reply","runs":"customer","why":"Send the grounded answer back to chat"}
{"t":"step","id":"hr-escalate","kind":"act","label":"Escalate to HR","effect":"notify","runs":"customer","why":"Forward unverified question to HR team"}
{"t":"step","id":"end-delivered","kind":"end","label":"Answer delivered","runs":"customer"}
{"t":"step","id":"end-escalated","kind":"end","label":"Escalated to HR","runs":"customer"}
{"t":"link","id":"in-guard","from":"chat-in","to":"input-guard"}
{"t":"link","id":"guard-embed","from":"input-guard","to":"embed"}
{"t":"link","id":"embed-search","from":"embed","to":"search"}
{"t":"link","id":"search-rerank","from":"search","to":"rerank"}
{"t":"link","id":"rerank-answer","from":"rerank","to":"answer"}
{"t":"link","id":"answer-output","from":"answer","to":"output-guard"}
{"t":"link","id":"output-route","from":"output-guard","to":"route"}
{"t":"link","id":"route-deliver","from":"route","to":"deliver","kind":"branch","label":"Grounded answer available"}
{"t":"link","id":"route-hr","from":"route","to":"hr-escalate","kind":"branch","label":"Insufficient evidence or unverified"}
{"t":"link","id":"deliver-end","from":"deliver","to":"end-delivered"}
{"t":"link","id":"hr-end","from":"hr-escalate","to":"end-escalated"}
{"t":"ask","id":"volume","text":"하루에 몇 건의 직원 질문이 예상됩니까?"}
{"t":"ask","id":"success","text":"성공 기준(예: 에스컬레이션 비율 감소)과 현재 수동 처리 현황은 어떻습니까?"}
{"t":"done","summary":"사내 정책 챗봇 워크플로우: 입력 가드, RAG 검색 및 리랭킹, 근거 기반 답변 생성 또는 거부, 출력 가드 후 라우팅하여 답변 전달 또는 HR 에스컬레이션."}

{"t":"say","text":"Prompt chain pattern: OCR extraction, policy retrieval, AI review, then human approval for payment decisions."}
{"t":"assume","id":"claim-vol","text":"Under 500 claims per day"}
{"t":"assume","id":"policy-store","text":"Insurance policies stored in DashVector"}
{"t":"step","id":"upload","kind":"trigger","label":"Receive claim upload","runs":"fc","untrusted":true,"private":true}
{"t":"step","id":"screen","kind":"guard","label":"Screen uploaded content","product":"ai-guardrails","runs":"fc","why":"Block prompt injection or harmful payloads before processing"}
{"t":"step","id":"route-doc","kind":"decide","label":"Route by file type","task":"classify","ai":"qwen3.8-flash","runs":"fc","why":"Direct images to vision OCR and PDFs to text parser"}
{"t":"step","id":"ocr-img","kind":"ai","label":"Extract image data","task":"extract","ai":"qwen3.7-plus","runs":"fc","why":"Vision model extracts structured fields from photos"}
{"t":"step","id":"parse-pdf","kind":"tool","label":"Parse PDF text","task":"extract","tool":"pdf_parse","runs":"fc","effect":"read","why":"Built-in tool extracts raw text from PDF documents"}
{"t":"step","id":"extract-pdf","kind":"ai","label":"Structure PDF fields","task":"extract","ai":"qwen3.8-flash","runs":"fc","after":"parse-pdf","why":"Small model structures raw PDF text into claim fields"}
{"t":"step","id":"embed","kind":"knowledge","label":"Embed claim context","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","why":"Vectorize extracted fields to find matching insurance policy"}
{"t":"step","id":"search-policy","kind":"knowledge","label":"Search insurance policy","task":"retrieve","product":"dashvector","runs":"fc","why":"Retrieve relevant policy clauses from vector store"}
{"t":"step","id":"rerank","kind":"knowledge","label":"Rerank policy clauses","task":"rerank","ai":"qwen3-rerank","runs":"fc","why":"Select the most relevant coverage terms for this claim"}
{"t":"step","id":"review","kind":"ai","label":"Review claim vs policy","task":"check","ai":"qwen3.8-max","runs":"fc","why":"Large model reasons over extracted data against policy terms"}
{"t":"step","id":"approve","kind":"human","label":"Approve payment decision","task":"approve","subject":"review","runs":"cloudflow","approval":"required","why":"Payment is a financial commitment requiring human gate per policy"}
{"t":"step","id":"pay","kind":"act","label":"Execute payment","effect":"pay","runs":"customer","why":"Call customer payment system after approval"}
{"t":"step","id":"paid","kind":"end","label":"Payment completed","runs":"customer"}
{"t":"step","id":"rejected","kind":"end","label":"Claim rejected","runs":"customer"}
{"t":"link","id":"upload-screen","from":"upload","to":"screen"}
{"t":"link","id":"screen-route","from":"screen","to":"route-doc"}
{"t":"link","id":"route-img","from":"route-doc","to":"ocr-img","kind":"branch","label":"Image file"}
{"t":"link","id":"route-pdf","from":"route-doc","to":"parse-pdf","kind":"branch","label":"PDF file"}
{"t":"link","id":"ocr-embed","from":"ocr-img","to":"embed"}
{"t":"link","id":"parse-extract","from":"parse-pdf","to":"extract-pdf"}
{"t":"link","id":"extract-embed","from":"extract-pdf","to":"embed"}
{"t":"link","id":"embed-search","from":"embed","to":"search-policy"}
{"t":"link","id":"search-rerank","from":"search-policy","to":"rerank"}
{"t":"link","id":"rerank-review","from":"rerank","to":"review"}
{"t":"link","id":"review-approve","from":"review","to":"approve"}
{"t":"link","id":"approve-pay","from":"approve","to":"pay","kind":"branch","outcome":"approve"}
{"t":"link","id":"approve-reject","from":"approve","to":"rejected","kind":"branch","outcome":"reject"}
{"t":"link","id":"approve-edit","from":"approve","to":"review","kind":"branch","outcome":"edit"}
{"t":"link","id":"pay-paid","from":"pay","to":"paid"}
{"t":"ask","id":"q-volume","text":"하루에 처리할 청구 건수는 대략 몇 건입니까?"}
{"t":"ask","id":"q-success","text":"성공 기준(예: 자동 승인률)과 현재 수동 처리 기준선은 무엇입니까?"}
{"t":"done","summary":"청구서 업로드부터 OCR/PDF 추출, 약관 검색, AI 심사, 인간 결제 승인까지의 프롬프트 체인 워크플로우를 설계했습니다."}

{"t":"say","text":"Prompt chain with agent sandbox recovery, admin approval gate before production changes, and guarded ticket handling."}
{"t":"assume","id":"channel","text":"Tickets arrive via webhook or API into EventBridge","alt":"Tickets arrive via email or chat channel"}
{"t":"assume","id":"kb-store","text":"Knowledge base is stored in DashVector","alt":"Knowledge base is stored in Milvus or Tablestore"}
{"t":"step","id":"ticket-in","kind":"trigger","label":"Receive support ticket","product":"eventbridge","runs":"fc","untrusted":true,"why":"Entry point for inbound IT tickets"}
{"t":"step","id":"guard","kind":"guard","label":"Screen ticket content","product":"ai-guardrails","runs":"fc","why":"Block prompt injection and harmful payloads"}
{"t":"step","id":"classify","kind":"ai","label":"Classify ticket issue","task":"classify","ai":"qwen3.8-flash","runs":"fc","why":"Route by category and severity"}
{"t":"step","id":"retrieve","kind":"knowledge","label":"Search knowledge base","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","why":"Find relevant runbooks and solutions"}
{"t":"step","id":"rerank","kind":"knowledge","label":"Rerank KB results","task":"rerank","ai":"qwen3-rerank","runs":"fc","why":"Prioritize most relevant documents"}
{"t":"step","id":"plan-recovery","kind":"ai","label":"Plan recovery steps","task":"plan","ai":"qwen3.7-plus","runs":"fc","after":"rerank","why":"Generate safe remediation plan from KB context"}
{"t":"step","id":"sandbox-fix","kind":"tool","label":"Execute in sandbox","task":"generate","tool":"code_interpreter","runs":"agentrun","after":"plan-recovery","effect":"write","why":"Run recovery scripts safely without touching production"}
{"t":"step","id":"check-scope","kind":"decide","label":"Check prod change scope","task":"check","ai":"qwen3.8-flash","runs":"fc","after":"sandbox-fix","why":"Determine if fix requires production environment changes"}
{"t":"step","id":"admin-approve","kind":"human","label":"Admin approves prod change","task":"approve","subject":"plan-recovery","runs":"cloudflow","approval":"required","why":"Gate all production modifications with explicit admin consent"}
{"t":"step","id":"apply-prod","kind":"act","label":"Apply production fix","effect":"admin","runs":"customer","why":"Execute approved changes on production systems"}
{"t":"step","id":"reply-user","kind":"act","label":"Reply to requester","effect":"reply","runs":"fc","after":"apply-prod","why":"Notify user of resolution status"}
{"t":"step","id":"end-resolved","kind":"end","label":"Ticket resolved","runs":"customer"}
{"t":"step","id":"end-rejected","kind":"end","label":"Change rejected","runs":"customer"}
{"t":"link","id":"in-guard","from":"ticket-in","to":"guard"}
{"t":"link","id":"guard-classify","from":"guard","to":"classify"}
{"t":"link","id":"classify-retrieve","from":"classify","to":"retrieve"}
{"t":"link","id":"retrieve-rerank","from":"retrieve","to":"rerank"}
{"t":"link","id":"rerank-plan","from":"rerank","to":"plan-recovery"}
{"t":"link","id":"plan-sandbox","from":"plan-recovery","to":"sandbox-fix"}
{"t":"link","id":"sandbox-check","from":"sandbox-fix","to":"check-scope"}
{"t":"link","id":"check-needs-prod","from":"check-scope","to":"admin-approve","kind":"branch","label":"Production change required"}
{"t":"link","id":"check-no-prod","from":"check-scope","to":"reply-user","kind":"branch","label":"Sandbox fix sufficient"}
{"t":"link","id":"approve-apply","from":"admin-approve","to":"apply-prod","kind":"branch","outcome":"approve"}
{"t":"link","id":"approve-reject","from":"admin-approve","to":"end-rejected","kind":"branch","outcome":"reject"}
{"t":"link","id":"approve-edit","from":"admin-approve","to":"plan-recovery","kind":"branch","outcome":"edit"}
{"t":"link","id":"apply-reply","from":"apply-prod","to":"reply-user"}
{"t":"link","id":"reply-end","from":"reply-user","to":"end-resolved"}
{"t":"ask","id":"volume","text":"하루에 접수되는 IT 지원 티켓 수는 대략 몇 건입니까?"}
{"t":"ask","id":"success","text":"성공 기준(예: 자동 해결률)과 현재 수동 처리 비율은 어떻게 됩니까?"}
{"t":"done","summary":"IT 지원 에이전트 워크플로우: 수신 분류, 지식 베이스 조회, 샌드박스 복구 실행 후 프로덕션 변경 시 관리자 승인 게이트 적용."}

{"t":"say","text":"Prompt chain pattern: transcribe sales call, extract CRM diff, human approves changes, then act writes to Salesforce."}
{"t":"assume","id":"audio-source","text":"Call audio arrives via webhook or file upload trigger"}
{"t":"assume","id":"sf-adapter","text":"Salesforce API adapter is available as a customer tool"}
{"t":"step","id":"call-in","kind":"trigger","label":"Receive call audio","runs":"fc","untrusted":true}
{"t":"step","id":"transcribe","kind":"ai","label":"Transcribe sales call","task":"transcribe","ai":"qwen-audio-3.1-asr-flash","runs":"fc","why":"Convert inbound audio to text for extraction"}
{"t":"step","id":"extract","kind":"ai","label":"Extract deal updates","task":"extract","ai":"qwen3.7-plus","runs":"fc","after":"transcribe","why":"Parse transcript into structured Salesforce field diffs"}
{"t":"step","id":"approve","kind":"human","label":"Approve CRM diff","task":"approve","subject":"extract","runs":"cloudflow","after":"extract","approval":"required","why":"Gate write effect; human must approve extracted changes before upsert"}
{"t":"step","id":"write-sf","kind":"act","label":"Write to Salesforce","effect":"write","runs":"customer","after":"approve","approval":"skip","why":"Apply approved diff to Salesforce via customer adapter"}
{"t":"step","id":"done-ok","kind":"end","label":"Deal updated","runs":"customer","after":"write-sf"}
{"t":"step","id":"rejected","kind":"end","label":"Update rejected","runs":"customer","after":"approve"}
{"t":"link","id":"in-transcribe","from":"call-in","to":"transcribe"}
{"t":"link","id":"transcribe-extract","from":"transcribe","to":"extract"}
{"t":"link","id":"extract-approve","from":"extract","to":"approve"}
{"t":"link","id":"approve-write","from":"approve","to":"write-sf","kind":"branch","outcome":"approve"}
{"t":"link","id":"approve-reject","from":"approve","to":"rejected","kind":"branch","outcome":"reject"}
{"t":"link","id":"approve-edit","from":"approve","to":"extract","kind":"branch","outcome":"edit"}
{"t":"link","id":"write-done","from":"write-sf","to":"done-ok"}
{"t":"ask","id":"vol","text":"하루에 처리할 영업 통화 건수는 몇 건인가요?"}
{"t":"ask","id":"success","text":"성공 기준(예: 추출 정확도)과 현재 수동 처리 소요 시간은 어떻게 되나요?"}
{"t":"done","summary":"영업 통화 전사, 딜 업데이트 추출, CloudFlow 기반 담당자 diff 승인 후 Salesforce 기록 워크플로우를 설계했습니다."}

{"t":"say","text":"Prompt chain pattern: collect identity, screen sanctions via tool, classify risk, escalate high-risk to compliance."}
{"t":"assume","id":"api-exists","text":"Sanctions screening API is available as a customer adapter","alt":"Use web search for public sanctions lists"}
{"t":"assume","id":"risk-criteria","text":"Risk criteria include PEP status, country and adverse media","alt":"Simpler rule-based risk scoring"}
{"t":"ask","id":"volume","text":"How many customer onboarding requests are processed per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's baseline false-positive rate?"}
{"t":"step","id":"start","kind":"trigger","label":"Onboarding request","runs":"customer","untrusted":true,"why":"Entry point for new customer onboarding"}
{"t":"step","id":"input-guard","kind":"guard","label":"Screen inbound data","product":"ai-guardrails","runs":"fc","why":"Prevent prompt injection in untrusted input"}
{"t":"step","id":"collect-id","kind":"ai","label":"Collect identity info","task":"extract","ai":"qwen3.7-plus","runs":"agentrun","private":true,"why":"Extract name, DOB, nationality, ID number from user input"}
{"t":"step","id":"screen-sanctions","kind":"tool","label":"Screen sanctions list","effect":"read","runs":"customer","private":true,"why":"Query external sanctions and PEP databases"}
{"t":"step","id":"assess-risk","kind":"ai","label":"Assess risk level","task":"classify","ai":"qwen3.8-max","runs":"agentrun","private":true,"why":"Combine identity and screening results to determine risk tier"}
{"t":"step","id":"route-risk","kind":"decide","label":"Route by risk","task":"decide","runs":"agentrun","why":"Branch workflow based on assessed risk level"}
{"t":"step","id":"low-risk-ok","kind":"end","label":"Approve onboarding","runs":"customer","why":"Low risk customers proceed automatically"}
{"t":"step","id":"compliance-review","kind":"human","label":"Compliance review","task":"approve","subject":"assess-risk","runs":"cloudflow","approval":"required","private":true,"why":"Human compliance officer reviews high-risk profiles, required for decide effect"}
{"t":"step","id":"record-decision","kind":"act","label":"Record decision","effect":"write","runs":"customer","private":true,"why":"Persist final compliance decision to core system"}
{"t":"step","id":"rejected","kind":"end","label":"Onboarding rejected","runs":"customer","why":"Terminal state for rejected applications"}
{"t":"link","id":"l-start-guard","from":"start","to":"input-guard"}
{"t":"link","id":"l-guard-collect","from":"input-guard","to":"collect-id"}
{"t":"link","id":"l-collect-screen","from":"collect-id","to":"screen-sanctions"}
{"t":"link","id":"l-screen-assess","from":"screen-sanctions","to":"assess-risk"}
{"t":"link","id":"l-assess-route","from":"assess-risk","to":"route-risk"}
{"t":"link","id":"l-route-low","from":"route-risk","to":"low-risk-ok","kind":"branch","label":"Low risk"}
{"t":"link","id":"l-route-high","from":"route-risk","to":"compliance-review","kind":"branch","label":"High risk or PEP match"}
{"t":"link","id":"l-comp-approve","from":"compliance-review","to":"record-decision","kind":"branch","outcome":"approve"}
{"t":"link","id":"l-comp-reject","from":"compliance-review","to":"rejected","kind":"branch","outcome":"reject"}
{"t":"done","summary":"Onboarding agent with identity extraction, sanctions screening, AI risk classification, and human compliance escalation for high-risk profiles."}

{"t":"say","text":"Prompt chain pattern: draft master copy, fan-out translate to 5 APAC locales in parallel, then human review before publish queue."}
{"t":"assume","id":"five-locales","text":"Five APAC target languages: Korean, Japanese, Chinese, Thai, Indonesian"}
{"t":"step","id":"brief-in","kind":"trigger","label":"Receive campaign brief","runs":"fc","untrusted":true,"why":"Entry point for the inbound English campaign brief"}
{"t":"step","id":"guard-brief","kind":"guard","label":"Screen inbound brief","product":"ai-guardrails","runs":"fc","why":"Block prompt injection or harmful content from untrusted input"}
{"t":"step","id":"draft-master","kind":"ai","label":"Draft master copy","task":"generate","ai":"qwen3.8-max","runs":"fc","why":"Large model produces high-quality English marketing copy"}
{"t":"each","id":"locales","over":"ko, ja, zh, th, id","parallel":true}
{"t":"step","id":"translate","kind":"ai","label":"Translate to locale","task":"translate","ai":"qwen3.7-plus","runs":"fc","repeat":"locales","why":"Mid-tier model handles multilingual translation per locale"}
{"t":"step","id":"assemble","kind":"ai","label":"Assemble localized package","task":"summarise","ai":"qwen3.8-flash","runs":"fc","join":"all","after":"translate","why":"Merge all translated copies into one delivery package"}
{"t":"step","id":"review","kind":"human","label":"Local market review","task":"approve","subject":"assemble","runs":"cloudflow","approval":"required","why":"Publishing marketing copy requires human approval per policy"}
{"t":"step","id":"publish-queue","kind":"act","label":"Push to publish queue","effect":"publish","runs":"customer","why":"Deliver approved package to the customer publishing system"}
{"t":"step","id":"done-pub","kind":"end","label":"Published to queue","runs":"customer"}
{"t":"step","id":"rejected","kind":"end","label":"Rejected by reviewer","runs":"customer"}
{"t":"link","id":"brief-guard","from":"brief-in","to":"guard-brief"}
{"t":"link","id":"guard-draft","from":"guard-brief","to":"draft-master"}
{"t":"link","id":"draft-translate","from":"draft-master","to":"translate"}
{"t":"link","id":"translate-assemble","from":"translate","to":"assemble"}
{"t":"link","id":"assemble-review","from":"assemble","to":"review"}
{"t":"link","id":"review-publish","from":"review","to":"publish-queue","kind":"branch","outcome":"approve"}
{"t":"link","id":"review-reject","from":"review","to":"rejected","kind":"branch","outcome":"reject"}
{"t":"link","id":"review-edit","from":"review","to":"draft-master","kind":"branch","outcome":"edit"}
{"t":"link","id":"pub-done","from":"publish-queue","to":"done-pub"}
{"t":"ask","id":"volume","text":"How many campaign briefs are processed per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's baseline turnaround time?"}
{"t":"done","summary":"Prompt chain that drafts English master copy, fans out parallel translation to 5 APAC locales, assembles a package, gates with human review, and publishes to the queue."}

{"t":"say","text":"Prompt chain pattern: research lead, draft personalized email, then human approval before sending via Direct Mail."}
{"t":"assume","id":"crm-adapter","text":"CRM lookup uses a customer adapter tool","alt":"CRM API exposed via MCP server"}
{"t":"assume","id":"lead-source","text":"New leads arrive via EventBridge webhook trigger","alt":"Scheduled polling for new CRM leads"}
{"t":"ask","id":"volume","text":"하루에 처리할 신규 리드 건수는 어느 정도인가요?"}
{"t":"ask","id":"success","text":"성공 기준(예: 회신율)과 현재 수동 처리 시 기준치가 있나요?"}
{"t":"step","id":"lead-in","kind":"trigger","label":"New CRM lead event","product":"eventbridge","runs":"fc","untrusted":true,"why":"Entry point for new lead events from CRM or form submissions"}
