{"t":"assume","id":"kyc-api","text":"Identity verification uses a third-party KYC service"}
{"t":"ask","id":"volume","text":"How many onboarding requests are processed per day?"}
{"t":"ask","id":"success","text":"What outcome defines success, and what is today's baseline approval rate?"}
{"t":"step","id":"trigger","kind":"trigger","label":"Onboarding request received","runs":"fc","untrusted":true,"private":true}
