{"t":"say","text":"Prompt chain pattern: inbound email trigger, guard, classify, retrieve, draft, human approve via CloudFlow callback, then send."}
{"t":"assume","id":"kb-store","text":"Knowledge base uses DashVector for retrieval"}
{"t":"step","id":"in","kind":"trigger","label":"Inbound email webhook","product":"eventbridge","runs":"fc","untrusted":true,"why":"Receive support emails via EventBridge webhook into Function Compute"}
{"t":"step","id":"guard","kind":"guard","label":"Screen inbound email","product":"ai-guardrails","runs":"fc","why":"Detect prompt injection and harmful content in untrusted input"}
{"t":"step","id":"classify","kind":"ai","label":"Classify support email","task":"classify","ai":"qwen3.8-flash","runs":"fc","why":"Route and tag the issue using a small fast model"}
{"t":"step","id":"retrieve","kind":"knowledge","label":"Retrieve help articles","task":"retrieve","product":"dashvector","ai":"text-embedding-v4","runs":"fc","effect":"read","why":"Fetch relevant knowledge base chunks for grounded drafting"}
{"t":"step","id":"rank","kind":"knowledge","label":"Rerank evidence","task":"rerank","ai":"qwen3-rerank","runs":"fc","why":"Order retrieved chunks by relevance before drafting"}
{"t":"step","id":"draft","kind":"ai","label":"Draft reply","task":"generate","ai":"qwen3.7-plus","runs":"fc","why":"Generate a grounded reply using mid-tier model with context"}
{"t":"step","id":"approve","kind":"human","label":"Approve reply","task":"approve","subject":"draft","runs":"cloudflow","why":"Human must approve exact email content before sending"}
{"t":"step","id":"send","kind":"act","label":"Send approved email","effect":"send","product":"direct-mail","runs":"fc","approval":"required","why":"Deliver the approved reply to the customer via Direct Mail"}
{"t":"step","id":"sent","kind":"end","label":"Email sent","runs":"customer","why":"Terminal state for successful delivery"}
{"t":"step","id":"rejected","kind":"end","label":"Rejected or timed out","runs":"customer","why":"Terminal state when approval is denied or times out"}
{"t":"link","id":"in-guard","from":"in","to":"guard","kind":"next","label":"Email received"}
{"t":"link","id":"guard-classify","from":"guard","to":"classify","kind":"next","label":"Safe content"}
{"t":"link","id":"classify-retrieve","from":"classify","to":"retrieve","kind":"next","label":"Classified"}
{"t":"link","id":"retrieve-rank","from":"retrieve","to":"rank","kind":"next","label":"Chunks found"}
{"t":"link","id":"rank-draft","from":"rank","to":"draft","kind":"next","label":"Ranked"}
{"t":"link","id":"draft-approve","from":"draft","to":"approve","kind":"next","label":"Draft ready"}
{"t":"link","id":"approve-send","from":"approve","to":"send","kind":"branch","outcome":"approve","label":"Approved"}
{"t":"link","id":"approve-edit","from":"approve","to":"draft","kind":"branch","outcome":"edit","label":"Needs revision"}
{"t":"link","id":"approve-reject","from":"approve","to":"rejected","kind":"branch","outcome":"reject","label":"Rejected"}
{"t":"link","id":"approve-timeout","from":"approve","to":"rejected","kind":"branch","outcome":"timeout","label":"Timed out"}
{"t":"link","id":"send-sent","from":"send","to":"sent","kind":"next","label":"Delivered"}
{"t":"ask","id":"volume","text":"How many support emails do you expect per day?"}
